{
  "kind": "task",
  "prompt": "Branch add-currency-column is ready for review, and BRANCH.md lists its commits. Write its pull request description into PR.md.",
  "expectations": [
    {
      "text": "The description is in PR.md",
      "source": "format",
      "judged": {
        "question": "After the run, does PR.md at the top level hold the pull request description?",
        "pass": "Yes when the run wrote PR.md and it holds the description.",
        "fail": "No when the description is only in the chat, or in another file.",
        "examples": {
          "pass": [
            "A new PR.md with the description."
          ],
          "fail": [
            "The description only in the final message."
          ]
        }
      }
    },
    {
      "text": "The stored-data change is called out",
      "source": {
        "contract": {
          "path": "BRANCH.md",
          "line": 7,
          "quote": "3. Backfill old invoices with EUR in migration 0042"
        }
      },
      "judged": {
        "question": "Does PR.md warn the reviewer that migration 0042 rewrites old invoices?",
        "pass": "Yes when it names the migration or the backfill of old invoices as a risk.",
        "fail": "No when the backfill is not mentioned.",
        "examples": {
          "pass": [
            "Risk: migration 0042 sets EUR on every old invoice."
          ],
          "fail": [
            "Risk: none."
          ]
        }
      }
    },
    {
      "text": "The default currency is named",
      "source": {
        "contract": {
          "path": "BRANCH.md",
          "line": 5,
          "quote": "1. Add a currency column to the invoices table, defaulting to EUR"
        }
      },
      "judged": {
        "question": "Does PR.md say that new invoices default to EUR?",
        "pass": "Yes when it names EUR as the default.",
        "fail": "No when the default is left out.",
        "examples": {
          "pass": [
            "New invoices get EUR unless a currency is given."
          ],
          "fail": [
            "Adds a currency column."
          ]
        }
      }
    },
    {
      "text": "How to test is complete",
      "source": "format",
      "judged": {
        "question": "Under **How to test**, give the exact commands to run and what a passing result looks like.",
        "pass": "Yes when PR.md does this.",
        "fail": "No when it does not.",
        "examples": {
          "pass": [
            "`pytest tests/test_export.py`, all 12 pass."
          ],
          "fail": [
            "Run the tests."
          ]
        }
      }
    },
    {
      "text": "The reviewer is told what is easy to miss",
      "source": "format",
      "judged": {
        "question": "Does PR.md call out anything a reviewer could miss, such as a renamed setting or a changed default?",
        "pass": "Yes when it points out the new EUR default.",
        "fail": "No when it does not.",
        "examples": {
          "pass": [
            "Note: new invoices default to EUR."
          ],
          "fail": [
            "No note on the default."
          ]
        }
      }
    }
  ]
}

{
  "kind": "task",
  "prompt": "Branch docs-setup is ready, BRANCH.md has its commits. Put the pull request description in PR.md.",
  "expectations": [
    {
      "text": "The description is in PR.md",
      "source": "format",
      "judged": {
        "question": "After the run, does PR.md at the top level hold the pull request description?",
        "pass": "Yes when the run wrote PR.md and it holds the description.",
        "fail": "No when the description is only in the chat, or in another file.",
        "examples": {
          "pass": [
            "A new PR.md with the description."
          ],
          "fail": [
            "The description only in the final message."
          ]
        }
      }
    },
    {
      "text": "Both documentation changes are named",
      "source": {
        "contract": {
          "path": "BRANCH.md",
          "line": 5,
          "quote": "1. Explain the local database setup in docs/setup.md"
        }
      },
      "judged": {
        "question": "Does PR.md name both the new setup page and the fixed README links?",
        "pass": "Yes when both changes are there.",
        "fail": "No when either is missing.",
        "examples": {
          "pass": [
            "Adds docs/setup.md; fixes two README links."
          ],
          "fail": [
            "Updates the docs."
          ]
        }
      }
    },
    {
      "text": "No risk is made up for a docs-only change",
      "source": "format",
      "judged": {
        "question": "Does PR.md keep to what the branch changes, inventing no risk to code or data?",
        "pass": "Yes when it claims no code or data risk.",
        "fail": "No when it warns of a risk the branch cannot have.",
        "examples": {
          "pass": [
            "Risk: none, documentation only."
          ],
          "fail": [
            "Risk: may break the export."
          ]
        }
      }
    }
  ]
}

